function normalized(raw){const p=raw.positions;let x=0,y=0,z=0;for(let i=0;i<p.length;i+=3){x=Math.max(x,Math.abs(p[i]));y=Math.max(y,p[i+1]);z=Math.max(z,Math.abs(p[i+2]));}const w=Math.max(x,z)*2||1;y=y||1;for(let i=0;i<p.length;i+=3){p[i]/=w;p[i+1]/=y;p[i+2]/=w;const n=unit([raw.normals[i]*w,raw.normals[i+1]*y,raw.normals[i+2]*w]);raw.normals.set(n,i);}return raw;}
function qualityFor(mode,count){if(count>1800)return 'mass';if(mode==='simple'||count>110)return 'low';if(mode==='standard'||count>24)return 'medium';return 'high';}
function massPlant(s,ap,seed){const b=builder(),r=rngFor(seed),g=rgb(s.kind==='grass'?'#829758':'#688849'),wood=rgb('#80694e'),woody=s.kind==='tree'||s.kind==='shrub';if(woody){b.tube([0,0,0],[0,.72,0],.045,.018,wood,4);for(let i=0;i<5;i++){const t=i*GOLD,p=radial(t,.28,.73+r()*.15);b.tube([0,.30,0],p,.019,.004,wood,3);if(!ap.leafless)for(let j=0;j<5;j++)b.leaf(p,add(p,radial(t+j*1.2,.20,r()*.18)),.10,tone(g,.8+r()*.35));}}else for(let i=0;i<9;i++){const t=i*GOLD;b.blade(t,.2+r()*.30,.32+r()*.60,.035,g,2);}return normalized(b.finish());}
function proxyPlant(s,ap,seed){const b=builder(),r=rngFor(seed),g=rgb(s.kind==='grass'?'#829758':'#688849'),wood=rgb('#80694e'),woody=s.kind==='tree'||s.kind==='shrub';if(woody){const shrub=s.kind==='shrub';b.tube([0,0,0],[0,shrub?.55:.75,0],.035,.012,wood,3);if(ap.leafless){for(let j=0;j<4;j++){const a=j*GOLD;b.tube([0,.25,0],radial(a,.44,.75+r()*.22),.016,.003,wood,3);}}else{const y=shrub?.52:.74,top=[0,1,0],bottom=[0,shrub?.12:.48,0];for(let j=0;j<6;j++){const a=radial(j*TAU/6,.48,y),c=radial((j+1)*TAU/6,.48,y);b.tri(top,a,c,tone(g,.83+r()*.30));b.tri(bottom,c,a,tone(g,.68+r()*.24));}}}else{for(let j=0;j<5;j++){const a=j*GOLD,tip=radial(a,.43,.55+r()*.40);b.leaf([0,0,0],tip,.065,tone(g,.8+r()*.35));}}return normalized(b.finish());}
function meshData(s,style,seed,quality,ap,month){if(quality==='proxy')return proxyPlant(s,ap,seed);if(quality==='mass')return massPlant(s,ap,seed);if(s.latin==='Muhlenbergia lindheimeri')return normalized(buildMuhly(seed,month===11||month===0||month===1?'dry':ap.bloom||month===-1?'mature':'leafy',quality));const green=s.kind==='tree'?'#587942':s.kind==='grass'?(month===11||month===0||month===1?'#ab9563':'#789659'):s.kind==='succulent'?'#769e82':'#71934d';return normalized(genericPlant(style,seed,quality,{green,color:ap.colors[0],leafless:ap.leafless,bloom:ap.bloom}));}
