function screenQuality(mode,pixels,count,previous){const high=previous==='high'?70:95,medium=previous==='medium'||previous==='high'?25:34,low=previous==='mass'?11:8;if(pixels<low)return 'mass';if(mode!=='simple'&&pixels>=medium){if(mode==='detailed'&&pixels>=high)return 'high';return 'medium';}return 'low';}
const qualityOrder=['proxy','mass','low','medium','high'];
function modelStage(month,ap){return [11,0,1].includes(month)?'dry':month===-1||ap.bloom?'mature':'leafy';}
function triangleEstimate(q,shared,style){if(q==='proxy')return 30;if(q==='mass')return 138;if(shared)return {low:10000,medium:40000,high:130000}[q];if(['canopy','airy','upright-tree','conifer','shrub'].includes(style))return {low:800,medium:4200,high:14000}[q];return {low:1400,medium:10000,high:45000}[q];}
function plantListKey(objects){return JSON.stringify(objects.map(o=>[o.id,o.species,o.x,o.y,o.w,o.height,o.angle||0]));}
function plantAssetKey(e,month){const {s,ap,style,q,shared}=e,variant=q==='high'?hash(e.id)%2:0,form=s.latin==='Muhlenbergia lindheimeri'?'legacy-muhly':style;if(q==='mass'||q==='proxy')return JSON.stringify([q,s.kind,form,['tree','shrub'].includes(s.kind)&&ap.leafless]);return JSON.stringify([q,s.kind,shared?'shared:'+shared.id:form,ap.leafless,ap.bloom,ap.colors[0]||'',variant,month]);}
function cacheTrim(cache,active,dispose,maxBytes=96*1024*1024,maxEntries=160){let bytes=0,evicted=0;for(const a of cache.values())bytes+=a.bytes;for(const [key,a] of cache){if(bytes<=maxBytes&&cache.size<=maxEntries)break;if(active.has(key))continue;dispose(a);cache.delete(key);bytes-=a.bytes;evicted++;}return {bytes,evicted};}
