function memoCost(get,keyOf){const local=new Map();return e=>{const key=keyOf(e);if(!local.has(key))local.set(key,get(key,e));return local.get(key);};}
function allocatePlantDetail(entries,mode,getAsset,budget=1800000){
 const ordered=[...entries].sort((a,b)=>entries.length>1800?((a.distance??Infinity)-(b.distance??Infinity)||b.pixels-a.pixels||String(a.id).localeCompare(String(b.id))):(b.pixels-a.pixels||String(a.id).localeCompare(String(b.id))));
 let used=0;const rows=ordered.map(e=>{const base={...e,q:'mass'},asset=getAsset(base);used+=asset.tri;return {e,entry:base,asset};});
 // Reserve room for visible foreground detail when the mass baseline nearly fills the budget.
 const baselineTarget=entries.length>1800?Math.floor(budget*.80):budget;
 for(let j=rows.length-1;j>=0&&used>baselineTarget;j--){const row=rows[j],entry={...row.e,q:'proxy'},asset=getAsset(entry);if(asset.tri<row.asset.tri){used+=asset.tri-row.asset.tri;row.entry=entry;row.asset=asset;}}
 for(const row of rows){const want=screenQuality(mode,row.e.pixels,entries.length,row.e.previous);let rank=qualityOrder.indexOf(want),floor=qualityOrder.indexOf(row.entry.q);for(;rank>floor;rank--){const q=qualityOrder[rank],remaining=budget-used;if(remaining<=0)break;const estimate=triangleEstimate(q,row.e.shared,row.e.style);if(q!=='mass'&&estimate>Math.max(1200,(remaining+row.asset.tri)*5))continue;const entry={...row.e,q},asset=getAsset(entry),delta=asset.tri-row.asset.tri;if(delta<=remaining){used+=delta;row.entry=entry;row.asset=asset;break;}}}
 return {rows,used};
}
// Aerial image shares the exact calibrated 2D footprint, on the terrain's UV coordinates.
function aerialRect(a,width,depth,tw,th){return [a.x/width*tw,a.y/depth*th,a.w/width*tw,a.h/depth*th];}
